INSERT INTO `places` (`id`, `uuid`, `name`, `slug`, `category_id`, `description`, `history`, `address`, `city`, `state`, `country`, `latitude`, `longitude`, `osm_id`, `osm_type`, `entry_fee`, `best_time_to_visit`, `status`, `avg_rating`, `total_reviews`, `total_favorites`, `source`, `created_by`, `created_at`, `updated_at`) VALUES
(1, '897c21ea-e65e-4257-8b21-5ab23b2c5c3d', 'Red Fort (Lal Qila)', 'red-fort-lal-qila', 5, 'The Red Fort is a historic Mughal fort located in the Old Delhi area of Delhi, India. Serving as the main residence of the Mughal emperors, it was commissioned by Emperor Shah Jahan on the 12th of May 1639; the fort was constructed following his decision to shift the Mughal capital from Agra to Delhi. Originally adorned in red and white, the fort\'s design is attributed to Ustad Ahmad Lahori, the architect of the Taj Mahal. The Red Fort is a prominent example of Mughal architecture from Shah Jahan\'s reign, combining Persian and Indian architectural styles.', 'The Red Fort (Lal Qila in Hindi; Hindi pronunciation: [laːl \'qɪlaː]) is a historic Mughal fort located in the Old Delhi area of Delhi, India. Serving as the main residence of the Mughal emperors, it was commissioned by Emperor Shah Jahan on the 12th of May 1639; the fort was constructed following his decision to shift the Mughal capital from Agra to Delhi. Originally adorned in red and white, the fort\'s design is attributed to Ustad Ahmad Lahori, the architect of the Taj Mahal. The Red Fort is a', '', 'Delhi', 'Delhi', 'India', 15.6562000, 77.2410000, NULL, NULL, '', '', 'published', 5.00, 1, 45, 'admin', NULL, '2026-07-28 12:48:16', '2026-07-31 13:58:48'),
(2, '874e57af-6e9c-4030-8fe6-28141e7efb9b', 'Qutub Minar', 'qutub-minar', 5, 'A UNESCO World Heritage Site in the Mehrauli area of South Delhi, India.', NULL, 'Seth Sarai, Mehrauli, New Delhi, Delhi 110030', 'Delhi', 'Delhi', 'India', 28.5245000, 77.1855000, NULL, NULL, '₹40 (Indian), ₹600 (Foreigner)', 'November to February', 'published', 4.00, 1, 89, 'admin', NULL, '2026-07-28 12:48:16', '2026-08-01 16:45:53'),
(3, '4ee44d0e-1328-4ed5-b96c-78e1e2cd7595', 'Lotus Temple', 'lotus-temple', 1, 'Notable for its lotuslike shape, it has become a prominent attraction in New Delhi.', NULL, 'Lotus Temple Rd, Bahapur, Shambhu Dayal Bagh, Kalkaji, New Delhi, Delhi 110019', 'Delhi', 'Delhi', 'India', 28.5535000, 77.2588000, NULL, NULL, 'Free', 'October to March', 'published', 5.00, 1, 35, 'admin', NULL, '2026-07-28 12:48:16', '2026-07-28 23:59:34'),
(4, '7c1fd0b0-78aa-445c-a275-bb5eb73f8fc0', 'India Gate', 'india-gate', 5, 'War memorial located astride the Rajpath, on the eastern edge of the ceremonial axis of New Delhi.', NULL, 'Rajpath, India Gate, New Delhi, Delhi 110001', 'Delhi', 'Delhi', 'India', 28.6129000, 77.2295000, NULL, NULL, 'Free', 'October to March', 'published', 4.00, 1, 120, 'admin', NULL, '2026-07-28 12:48:16', '2026-07-29 11:08:04'),
