(10, '60308cda-4790-428a-aca5-583da6ea4275', 'Suryadev', 'suryadev', 5, 'Tourist location in Delhi', NULL, NULL, 'Delhi', NULL, 'India', 28.7950429, 77.1444274, 496728650, 'node', NULL, NULL, 'published', 0.00, 0, 0, 'osm', NULL, '2026-07-29 12:09:25', '2026-07-29 12:22:17'),
(11, '2bb871be-6612-4b5e-b5c0-f6fd351a868d', 'Parliament Reception', 'parliament-reception', 5, 'The Cockroach Janta Party, also known as the Cockroach movement, is an Indian youth-based satirical political movement founded on 16 May 2026 by Abhijeet Dipke, a political communications strategist and activist.', 'The Cockroach Janta Party (CJP; lit. \'Cockroach People\'s Party\'), also known as the Cockroach movement, is an Indian youth-based satirical political movement founded on 16 May 2026 by Abhijeet Dipke, a political communications strategist and activist.\nIt was created in response to remarks made on 15 May 2026 by Surya Kant, the Chief Justice of India, in which he referred to certain activists and unemployed youth as \"cockroaches\" and \"parasites of society\", sparking widespread public reaction. Ka', NULL, 'Delhi', NULL, 'India', 28.6163882, 77.2099346, 561254915, 'node', NULL, NULL, 'published', 5.00, 1, 0, 'osm', NULL, '2026-07-29 12:09:25', '2026-08-01 02:20:40'),
