(1024, 'df34b989-3b04-4243-8d37-a3c75ba67da5', 'Kotla Firoz Shah Palace', 'kotla-firoz-shah-palace', 5, 'The Feroz Shah Kotla or Kotla was a fortress built circa 1354 by Feroz Shah Tughlaq to house his version of Delhi called Firozabad.', 'The Feroz Shah Kotla or Kotla (\"fortress\", \"citadel\") was a fortress built circa 1354 by Feroz Shah Tughlaq to house his version of Delhi called Firozabad.\nA pristine polished sandstone Topra Ashokan pillar from the 3rd century BC rises from the palace\'s crumbling remains, one of many pillars of Ashoka left by the Mauryan emperor; it was moved from Topra Kalan in Pong Ghati of Yamunanagar district in Haryana to Delhi under orders of Firoz Shah Tughlaq of Delhi Sultanate, and re-erected in its pr', NULL, 'Delhi', NULL, 'India', 28.6346414, 77.2447758, 97230898, 'way', NULL, NULL, 'published', 0.00, 0, 0, 'osm', NULL, '2026-07-29 12:09:38', '2026-07-29 13:09:30'),
(1025, '9d045914-bbd0-4ee0-a542-643ffbc2c851', 'Baoli', 'baoli', 5, 'Tourist location in Delhi', NULL, NULL, 'Delhi', NULL, 'India', 28.6359910, 77.2446801, 97230899, 'way', NULL, NULL, 'published', 0.00, 0, 0, 'osm', NULL, '2026-07-29 12:09:38', '2026-07-29 12:22:17'),
(1026, '55b56a95-2209-468a-bb2d-742a20e96d41', 'Crowne Plaza', 'crowne-plaza', 5, 'Kerala Fashion League (KFL) is an annual fashion event held in Crowne Plaza, Kochi, India that provides opportunities to designers to showcase their collections. It was founded in 2015 by Abhil dev. The first season of Kerala Fashion League was held at Kochi on 27 May 2015.', 'Kerala Fashion League (KFL) is an annual fashion event held in Crowne Plaza, Kochi, India that provides opportunities to designers to showcase their collections. It was founded in 2015 by Abhil dev. The first season of Kerala Fashion League was held at Kochi on 27 May 2015.\nKFL aims at promoting local designers and displaying their collection along with the leading brands in the country. It also serves as a platform to young aspiring models to display their talent.\n\n\n== Activities ==\nThrough man', NULL, 'Delhi', NULL, 'India', 28.5286687, 77.2725913, 102522853, 'way', NULL, NULL, 'published', 0.00, 0, 0, 'osm', NULL, '2026-07-29 12:09:38', '2026-07-31 15:07:03'),
