(1433, 'a786f2f4-f8b2-470f-8807-f0ebc528decf', 'sai baba temple', 'sai-baba-temple', 1, 'Ekkirala Bharadwaj, was an Indian who authored many Hindu spiritual books, primarily on the life and worship of Shirdi Sai Baba and Sri Dattatreya. He is the fourth son of Ekkirala Ananthacharya and Buchamma. Ekkirala Bharadwaj written Telugu-language book Sri Sai Leelamrutham is a notable book. Ekkirala Bharadwaja later translated the book to English with the name Sai Baba The Master. He also wrote \"Sri Guru Charitra\" in English and Telugu. He also has written many spiritual books in Telugu and English.', 'Ekkirala Bharadwaj (30 October 1938 – 12 April 1989), was an Indian who authored many Hindu spiritual books, primarily on the life and worship of Shirdi Sai Baba and Sri Dattatreya. He is the fourth son of Ekkirala Ananthacharya and Buchamma. Ekkirala Bharadwaj written Telugu-language book Sri Sai Leelamrutham is a notable book (Parayana Grandam). Ekkirala Bharadwaja later translated the book to English with the name Sai Baba The Master. He also wrote \"Sri Guru Charitra\" in English and Telugu.  ', NULL, 'ongole', NULL, 'India', 15.4933296, 80.0531782, 7246526635, 'node', NULL, NULL, 'published', 0.00, 0, 0, 'osm', NULL, '2026-07-31 19:05:18', '2026-07-31 22:14:42'),
(1434, 'f69a1400-1641-43cf-9e1a-97a6e1e1cf55', 'Lord venkateswara temple', 'lord-venkateswara-temple', 1, 'Tirumala Tirupati Devasthanams (TTD) is a trust set up by the Government of Andhra Pradesh, India. The trust primarily oversees the operations and finances of the richest and the most visited religious center Venkateswara Temple, Tirumala. It is also involved in various social, religious, literary and educational activities. TTD is headquartered at Tirupati in Andhra Pradesh, India and employs about 16,000 people.', 'Tirumala Tirupati Devasthanams (TTD) is a trust set up by the Government of Andhra Pradesh, India. The trust primarily oversees the operations and finances of the richest and the most visited religious center Venkateswara Temple, Tirumala. It is also involved in various social, religious, literary and educational activities. TTD is headquartered at Tirupati in Andhra Pradesh, India and employs about 16,000 people.\nSrivani trust was set up by TTD in 2019 to promote Sanātana Dharma by constructing', NULL, 'ongole', NULL, 'India', 15.5010132, 80.0453615, 7246755116, 'node', NULL, NULL, 'published', 0.00, 0, 0, 'osm', NULL, '2026-07-31 19:05:18', '2026-07-31 19:32:24'),
