(19, '9308372e-8fbf-4f0d-82ee-667d6f2606b5', 1, 'Mysore', '3 Day Itinerary in Mysore', '3 Days', 'Moderate', '[{\"day\": 1, \"theme\": \"Day 1 \\u2014 Highlights of Mysore\", \"activities\": [{\"time\": \"09:30 AM\", \"place_slug\": \"red-fort-lal-qila\", \"place_name\": \"Red Fort (Lal Qila)\", \"reason\": \"Top rated historical spot in Mysore, ideal for day 1.\", \"travel_minutes\": 0, \"estimated_duration\": \"2h\"}, {\"time\": \"01:30 PM\", \"place_slug\": \"lotus-temple\", \"place_name\": \"Lotus Temple\", \"reason\": \"Top rated temple spot in Mysore, ideal for day 1.\", \"travel_minutes\": 1367, \"estimated_duration\": \"2h\"}, {\"time\": \"05:00 PM\", \"place_slug\": \"qutub-minar\", \"place_name\": \"Qutub Minar\", \"reason\": \"Top rated historical spot in Mysore, ideal for day 1.\", \"travel_minutes\": 14, \"estimated_duration\": \"2h\"}, {\"time\": \"07:30 PM\", \"place_slug\": \"india-gate\", \"place_name\": \"India Gate\", \"reason\": \"Top rated historical spot in Mysore, ideal for day 1.\", \"travel_minutes\": 12, \"estimated_duration\": \"2h\"}, {\"time\": \"09:30 AM\", \"place_slug\": \"dandi-march-statue-(11-murthi)\", \"place_name\": \"Dandi March Statue (11 Murthi)\", \"reason\": \"Top rated historical spot in Mysore, ideal for day 1.\", \"travel_minutes\": 6, \"estimated_duration\": \"2h\"}, {\"time\": \"01:30 PM\", \"place_slug\": \"teen-murti-haifa-war-memorial\", \"place_name\": \"Teen Murti Haifa War Memorial\", \"reason\": \"Top rated museum spot in Mysore, ideal for day 1.\", \"travel_minutes\": 2, \"estimated_duration\": \"2h\"}, {\"time\": \"05:00 PM\", \"place_slug\": \"the-ambassador\", \"place_name\": \"The Ambassador\", \"reason\": \"Top rated historical spot in Mysore, ideal for day 1.\", \"travel_minutes\": 5, \"estimated_duration\": \"2h\"}, {\"time\": \"07:30 PM\", \"place_slug\": \"radisson-blu-plaza-hotel,delhi-airport\", \"place_name\": \"Radisson Blu Plaza Hotel,Delhi Airport\", \"reason\": \"Top rated historical spot in Mysore, ideal for day 1.\", \"travel_minutes\": 19, \"estimated_duration\": \"2h\"}, {\"time\": \"09:30 AM\", \"place_slug\": \"hotel-surya\", \"place_name\": \"Hotel Surya\", \"reason\": \"Top rated historical spot in Mysore, ideal for day 1.\", \"travel_minutes\": 26, \"estimated_duration\": \"2h\"}, {\"time\": \"01:30 PM\", \"place_slug\": \"suryadev\", \"place_name\": \"Suryadev\", \"reason\": \"Top rated historical spot in Mysore, ideal for day 1.\", \"travel_minutes\": 39, \"estimated_duration\": \"2h\"}]}, {\"day\": 2, \"theme\": \"Day 2 \\u2014 Highlights of Mysore\", \"activities\": [{\"time\": \"09:30 AM\", \"place_slug\": \"parliament-reception\", \"place_name\": \"Parliament Reception\", \"reason\": \"Top rated historical spot in Mysore, ideal for day 2.\", \"travel_minutes\": 0, \"estimated_duration\": \"2h\"}, {\"time\": \"01:30 PM\", \"place_slug\": \"kisan-ghat\", \"place_name\": \"Kisan Ghat\", \"reason\": \"Top rated historical spot in Mysore, ideal for day 2.\", \"travel_minutes\": 9, \"estimated_duration\": \"2h\"}, {\"time\": \"05:00 PM\", \"place_slug\": \"master-guest-house\", \"place_name\": \"Master Guest House\", \"reason\": \"Top rated historical spot in Mysore, ideal for day 2.\", \"travel_minutes\": 13, \"estimated_duration\": \"2h\"}, {\"time\": \"07:30 PM\", \"place_slug\": \"jaypee-vasant-continental-hotel\", \"place_name\": \"Jaypee Vasant Continental Hotel\", \"reason\": \"Top rated historical spot in Mysore, ideal for day 2.\", \"travel_minutes\": 16, \"estimated_duration\": \"2h\"}, {\"time\": \"09:30 AM\", \"place_slug\": \"parkland-hotel\", \"place_name\": \"Parkland Hotel\", \"reason\": \"Top rated park spot in Mysore, ideal for day 2.\", \"travel_minutes\": 12, \"estimated_duration\": \"2h\"}, {\"time\": \"01:30 PM\", \"place_slug\": \"vishal-residency-hotel\", \"place_name\": \"Vishal Residency Hotel\", \"reason\": \"Top rated historical spot in Mysore, ideal for day 2.\", \"travel_minutes\": 20, \"estimated_duration\": \"2h\"}, {\"time\": \"05:00 PM\", \"place_slug\": \"yatri-guesthouse\", \"place_name\": \"Yatri Guesthouse\", \"reason\": \"Top rated historical spot in Mysore, ideal for day 2.\", \"travel_minutes\": 23, \"estimated_duration\": \"2h\"}, {\"time\": \"07:30 PM\", \"place_slug\": \"hotel-metropolis\", \"place_name\": \"Hotel Metropolis\", \"reason\": \"Top rated historical spot in Mysore, ideal for day 2.\", \"travel_minutes\": 2, \"estimated_duration\": \"2h\"}, {\"time\": \"09:30 AM\", \"place_slug\": \"diwan-e-aam\", \"place_name\": \"Diwan-e-Aam\", \"reason\": \"Top rated historical spot in Mysore, ideal for day 2.\", \"travel_minutes\": 9, \"estimated_duration\": \"2h\"}, {\"time\": \"01:30 PM\", \"place_slug\": \"hotel-tara-palace\", \"place_name\": \"Hotel Tara Palace\", \"reason\": \"Top rated historical spot in Mysore, ideal for day 2.\", \"travel_minutes\": 4, \"estimated_duration\": \"2h\"}]}, {\"day\": 3, \"theme\": \"Day 3 \\u2014 Highlights of Mysore\", \"activities\": [{\"time\": \"09:30 AM\", \"place_slug\": \"star-paradise\", \"place_name\": \"Star Paradise\", \"reason\": \"Top rated historical spot in Mysore, ideal for day 3.\", \"travel_minutes\": 0, \"estimated_duration\": \"2h\"}, {\"time\": \"01:30 PM\", \"place_slug\": \"octagonal-observation-post\", \"place_name\": \"Octagonal observation post\", \"reason\": \"Top rated historical spot in Mysore, ideal for day 3.\", \"travel_minutes\": 16, \"estimated_duration\": \"2h\"}, {\"time\": \"05:00 PM\", \"place_slug\": \"bijaymandal-hall-ruins\", \"place_name\": \"Bijaymandal Hall Ruins\", \"reason\": \"Top rated historical spot in Mysore, ideal for day 3.\", \"travel_minutes\": 0, \"estimated_duration\": \"2h\"}, {\"time\": \"07:30 PM\", \"place_slug\": \"dome\", \"place_name\": \"Dome\", \"reason\": \"Top rated historical spot in Mysore, ideal for day 3.\", \"travel_minutes\": 0, \"estimated_duration\": \"2h\"}, {\"time\": \"09:30 AM\", \"place_slug\": \"munda-gumbad\", \"place_name\": \"Munda Gumbad\", \"reason\": \"Top rated historical spot in Mysore, ideal for day 3.\", \"travel_minutes\": 7, \"estimated_duration\": \"2h\"}, {\"time\": \"01:30 PM\", \"place_slug\": \"unidentified-tomb\", \"place_name\": \"Unidentified Tomb\", \"reason\": \"Top rated historical spot in Mysore, ideal for day 3.\", \"travel_minutes\": 8, \"estimated_duration\": \"2h\"}, {\"time\": \"05:00 PM\", \"place_slug\": \"information-board-for-balban\'s-tomb\", \"place_name\": \"Information Board for Balban\'s Tomb\", \"reason\": \"Top rated historical spot in Mysore, ideal for day 3.\", \"travel_minutes\": 13, \"estimated_duration\": \"2h\"}, {\"time\": \"07:30 PM\", \"place_slug\": \"tombs\", \"place_name\": \"Tombs\", \"reason\": \"Top rated historical spot in Mysore, ideal for day 3.\", \"travel_minutes\": 5, \"estimated_duration\": \"2h\"}, {\"time\": \"09:30 AM\", \"place_slug\": \"tomb\", \"place_name\": \"Tomb\", \"reason\": \"Top rated historical spot in Mysore, ideal for day 3.\", \"travel_minutes\": 0, \"estimated_duration\": \"2h\"}, {\"time\": \"01:30 PM\", \"place_slug\": \"gateway-guest-house-(metcalfe\'s-retreat)\", \"place_name\": \"Gateway Guest House (Metcalfe\'s Retreat)\", \"reason\": \"Top rated historical spot in Mysore, ideal for day 3.\", \"travel_minutes\": 2, \"estimated_duration\": \"2h\"}]}]', '{\"summary\": \"A curated 3-day travel plan exploring top attractions and heritage in Mysore.\", \"travel_tips\": [\"Check morning operating hours before starting your tour in Mysore.\", \"Current weather forecast indicates Partly Cloudy.\", \"Carry local currency and water during afternoon walking tours.\"], \"original_prompt\": \"3-day trip to Mysore\", \"theme\": \"Heritage & Culture\"}', '{\"weather_summary\": {\"temperature_c\": 22.7, \"condition\": \"Partly Cloudy\", \"humidity_pct\": 60, \"rain_probability_pct\": 75, \"uv_index\": 5, \"recommendation\": \"Great weather for outdoor activities.\"}}', '2026-08-01 00:41:31', '2026-08-01 00:41:31'),
(20, '3c1955b7-f59c-41b3-985d-b0f4af91bf1d', 1, 'Mysore', '3 Day Itinerary in Mysore', '3 Days', 'Moderate', '[{\"day\": 1, \"theme\": \"Historical and Cultural Exploration\", \"activities\": [{\"time\": \"09:00 AM\", \"place_slug\": \"mysore-palace\", \"place_name\": \"Mysore Palace\", \"reason\": \"A must-visit iconic landmark showcasing the grandeur of Mysore\'s royal heritage and stunning architecture.\", \"travel_minutes\": 10, \"estimated_duration\": \"2h\"}, {\"time\": \"01:00 PM\", \"place_slug\": \"chamundi-hills\", \"place_name\": \"Chamundi Hills\", \"reason\": \"Enjoy panoramic views of Mysore and visit the famous Chamundeshwari Temple, a significant religious site.\", \"travel_minutes\": 20, \"estimated_duration\": \"2h\"}, {\"time\": \"04:30 PM\", \"place_slug\": \"brindavan-gardens\", \"place_name\": \"Brindavan Gardens\", \"reason\": \"Relax in these beautifully landscaped gardens, famous for their musical fountain show in the evening.\", \"travel_minutes\": 30, \"estimated_duration\": \"1.5h\"}, {\"time\": \"07:30 PM\", \"place_slug\": \"devaraja-market\", \"place_name\": \"Devaraja Market\", \"reason\": \"Experience the local culture and shop for spices, flowers, and traditional Mysore silk sarees.\", \"travel_minutes\": 15, \"estimated_duration\": \"1.5h\"}]}, {\"day\": 2, \"theme\": \"Art and Nature Appreciation\", \"activities\": [{\"time\": \"09:00 AM\", \"place_slug\": \"jaganmohan-palace-art-gallery\", \"place_name\": \"Jaganmohan Palace Art Gallery\", \"reason\": \"Discover a rich collection of traditional and contemporary art, including works by Raja Ravi Varma.\", \"travel_minutes\": 10, \"estimated_duration\": \"2h\"}, {\"time\": \"01:00 PM\", \"place_slug\": \"rail-museum\", \"place_name\": \"Rail Museum\", \"reason\": \"Explore the history of Indian railways with vintage locomotives and fascinating exhibits.\", \"travel_minutes\": 15, \"estimated_duration\": \"1.5h\"}, {\"time\": \"04:30 PM\", \"place_slug\": \"karanji-lake\", \"place_name\": \"Karanji Lake\", \"reason\": \"Unwind with a peaceful walk around this scenic lake, home to a variety of bird species and a butterfly park.\", \"travel_minutes\": 10, \"estimated_duration\": \"1.5h\"}]}, {\"day\": 3, \"theme\": \"Spiritual and Local Experiences\", \"activities\": [{\"time\": \"09:00 AM\", \"place_slug\": \"st-philomena-s-church\", \"place_name\": \"St. Philomena\'s Church\", \"reason\": \"Visit one of the largest churches in India, known for its stunning Gothic architecture and serene atmosphere.\", \"travel_minutes\": 10, \"estimated_duration\": \"1.5h\"}, {\"time\": \"01:00 PM\", \"place_slug\": \"sri-jayachamarajendra-art-gallery\", \"place_name\": \"Sri Jayachamarajendra Art Gallery\", \"reason\": \"Admire an impressive collection of paintings, sculptures, and musical instruments in this historic gallery.\", \"travel_minutes\": 10, \"estimated_duration\": \"1.5h\"}, {\"time\": \"04:30 PM\", \"place_slug\": \"mysore-zoo\", \"place_name\": \"Mysore Zoo\", \"reason\": \"Spend your final afternoon exploring one of India\'s oldest and most well-maintained zoos, home to diverse wildlife.\", \"travel_minutes\": 15, \"estimated_duration\": \"2h\"}]}]', '{\"summary\": \"Explore the rich cultural and historical heritage of Mysore with a curated 3-day sightseeing trip, featuring iconic landmarks and local gems. Enjoy the pleasant weather while immersing yourself in the city\'s vibrant history and architecture.\", \"travel_tips\": [\"Carry an umbrella or raincoat due to a 75% chance of rain; mornings are ideal for outdoor activities to avoid afternoon showers.\", \"Visit historical sites early in the day to avoid crowds and make the most of the cooler temperatures.\"], \"original_prompt\": \"3-day trip to Mysore\", \"theme\": \"Heritage & Culture\"}', '{\"weather_summary\": {\"temperature_c\": 22.7, \"condition\": \"Partly Cloudy\", \"humidity_pct\": 60, \"rain_probability_pct\": 75, \"recommendation\": \"Great weather for outdoor activities, but be prepared for sudden rain showers.\"}}', '2026-08-01 00:53:04', '2026-08-01 00:53:04'),
