(22, '8e2f3dcf-14fd-4b0f-bcd3-b35a0f982be5', 1, 'Tirupati', '2 Day Itinerary in Tirupati', '2 Days', 'Moderate', '[{\"day\": 1, \"theme\": \"Spiritual and Cultural Exploration\", \"activities\": [{\"time\": \"09:00 AM\", \"place_slug\": \"govindarajaswamy-temple\", \"place_name\": \"Govindarajaswamy Temple\", \"reason\": \"Start your day with a visit to this ancient temple, one of the most significant in Tirupati, known for its architectural beauty and spiritual ambiance.\", \"travel_minutes\": 0, \"estimated_duration\": \"2h\"}, {\"time\": \"01:00 PM\", \"place_slug\": \"sri-kodanda-rama-swamy-temple\", \"place_name\": \"Sri Kodanda Rama Swamy Temple\", \"reason\": \"Explore this historic temple dedicated to Lord Rama, offering a serene environment for reflection and prayer.\", \"travel_minutes\": 2, \"estimated_duration\": \"1.5h\"}, {\"time\": \"04:30 PM\", \"place_slug\": \"annamacharya-kalamandiram\", \"place_name\": \"Annamacharya Kalamandiram\", \"reason\": \"Discover the life and works of Annamacharya, a revered saint and composer, in this cultural museum.\", \"travel_minutes\": 1, \"estimated_duration\": \"1.5h\"}, {\"time\": \"07:30 PM\", \"place_slug\": \"thathayyagunta-gangamma-temple\", \"place_name\": \"Thathayyagunta Gangamma Temple\", \"reason\": \"Conclude your day with a visit to this local temple, known for its unique traditions and evening rituals.\", \"travel_minutes\": 2, \"estimated_duration\": \"1h\"}]}, {\"day\": 2, \"theme\": \"Heritage and Local Temples\", \"activities\": [{\"time\": \"09:00 AM\", \"place_slug\": \"sri-vinayaka-swamy-temple\", \"place_name\": \"Sri Vinayaka Swamy Temple\", \"reason\": \"Begin your day with blessings at this temple dedicated to Lord Ganesha, a symbol of new beginnings.\", \"travel_minutes\": 0, \"estimated_duration\": \"1.5h\"}, {\"time\": \"01:00 PM\", \"place_slug\": \"sri-karumariamman-temple\", \"place_name\": \"Sri Karumariamman Temple\", \"reason\": \"Visit this temple dedicated to Goddess Karumariamman, known for its vibrant festivals and spiritual significance.\", \"travel_minutes\": 1, \"estimated_duration\": \"1.5h\"}, {\"time\": \"04:30 PM\", \"place_slug\": \"m-s-subbalakshmi-memorial-statue\", \"place_name\": \"M S Subbalakshmi Memorial Statue\", \"reason\": \"Pay homage to the legendary Carnatic singer M.S. Subbulakshmi at this memorial, celebrating her contributions to music.\", \"travel_minutes\": 2, \"estimated_duration\": \"1h\"}, {\"time\": \"07:30 PM\", \"place_slug\": \"sri-shiridi-sai-baba-temple\", \"place_name\": \"Sri Shiridi Sai Baba Temple\", \"reason\": \"End your trip with a peaceful visit to this temple, dedicated to Sai Baba, offering a tranquil atmosphere for meditation.\", \"travel_minutes\": 3, \"estimated_duration\": \"1h\"}]}]', '{\"summary\": \"Explore the spiritual and historical essence of Tirupati with visits to iconic temples and cultural landmarks. Experience the divine atmosphere and rich heritage of this sacred city.\", \"travel_tips\": [\"Carry an umbrella or raincoat due to a 30% chance of rain, and dress modestly when visiting temples.\", \"Visit temples early in the morning to avoid crowds and enjoy a peaceful experience.\"], \"original_prompt\": \"tirupati\", \"theme\": \"Heritage & Culture\"}', '{\"weather_summary\": {\"temperature_c\": 26.7, \"condition\": \"Partly Cloudy\", \"humidity_pct\": 60, \"rain_probability_pct\": 30, \"recommendation\": \"Great weather for outdoor activities.\"}}', '2026-08-01 01:14:50', '2026-08-01 01:14:50'),
(23, '531f610b-905e-4449-92fa-74809ecc7b52', 1, 'Chittoor', '2 Day Temple Itinerary in Chittoor', '2 Days', 'Moderate', '[{\"day\": 1, \"theme\": \"Sacred Temples and Spiritual Beginnings\", \"activities\": [{\"time\": \"09:00 AM\", \"place_slug\": \"sri-padmavathi-ammavari-temple\", \"place_name\": \"Sri Padmavathi Ammavari Temple\", \"reason\": \"A revered temple dedicated to Goddess Padmavathi, offering a serene start to your spiritual journey.\", \"travel_minutes\": 0, \"estimated_duration\": \"2h\"}, {\"time\": \"01:00 PM\", \"place_slug\": \"hanuman-and-shiva-temple\", \"place_name\": \"Hanuman And Shiva Temple\", \"reason\": \"A unique temple combining the worship of Lord Hanuman and Lord Shiva, perfect for an afternoon of devotion.\", \"travel_minutes\": 15, \"estimated_duration\": \"1.5h\"}, {\"time\": \"04:30 PM\", \"place_slug\": \"nagamma-temple\", \"place_name\": \"Nagamma Temple\", \"reason\": \"Experience the local folklore and spiritual significance of this temple dedicated to Nagamma.\", \"travel_minutes\": 19, \"estimated_duration\": \"1.5h\"}, {\"time\": \"07:30 PM\", \"place_slug\": \"shrine\", \"place_name\": \"Shrine\", \"reason\": \"Conclude your day with a peaceful visit to this local shrine, reflecting on the day\'s spiritual experiences.\", \"travel_minutes\": 18, \"estimated_duration\": \"1h\"}]}, {\"day\": 2, \"theme\": \"Cultural and Historical Exploration\", \"activities\": [{\"time\": \"09:00 AM\", \"place_slug\": \"m-s-subbalakshmi-memorial-statue\", \"place_name\": \"M S Subbalakshmi Memorial Statue\", \"reason\": \"Pay homage to the legendary Carnatic musician M.S. Subbalakshmi, a cultural icon of India.\", \"travel_minutes\": 0, \"estimated_duration\": \"1.5h\"}, {\"time\": \"01:00 PM\", \"place_slug\": \"vivekananda-circle\", \"place_name\": \"Vivekananda Circle\", \"reason\": \"A historical landmark dedicated to Swami Vivekananda, offering a moment of inspiration and reflection.\", \"travel_minutes\": 4, \"estimated_duration\": \