(25, 'cf127a04-94d8-43e5-8c67-48d2ba3a538f', 1, 'Goa', '2 Day Itinerary in Goa', '2 Days', 'Moderate', '[{\"day\": 1, \"theme\": \"Historical Exploration & Local Culture\", \"activities\": [{\"time\": \"09:00 AM\", \"place_slug\": \"red-fort-lal-qila\", \"place_name\": \"Red Fort (Lal Qila)\", \"reason\": \"Start your day with a visit to one of India\'s most iconic historical landmarks, offering rich insights into Mughal architecture and history.\", \"travel_minutes\": 0, \"estimated_duration\": \"2h\"}, {\"time\": \"01:00 PM\", \"place_slug\": \"qutub-minar\", \"place_name\": \"Qutub Minar\", \"reason\": \"Explore the tallest brick minaret in the world, a UNESCO World Heritage Site, and delve into Delhi\'s ancient history.\", \"travel_minutes\": 1370, \"estimated_duration\": \"1.5h\"}, {\"time\": \"04:30 PM\", \"place_slug\": \"india-gate\", \"place_name\": \"India Gate\", \"reason\": \"Visit this war memorial to pay respects and enjoy a peaceful walk around its lush surroundings, ideal for sunset views.\", \"travel_minutes\": 12, \"estimated_duration\": \"1h\"}, {\"time\": \"07:30 PM\", \"place_slug\": \"lotus-temple\", \"place_name\": \"Lotus Temple\", \"reason\": \"End your day with a serene visit to this architectural marvel, perfect for reflection and photography, especially when lit up in the evening.\", \"travel_minutes\": 13, \"estimated_duration\": \"1h\"}]}, {\"day\": 2, \"theme\": \"Museums & Relaxation\", \"activities\": [{\"time\": \"09:00 AM\", \"place_slug\": \"teen-murti-haifa-war-memorial\", \"place_name\": \"Teen Murti Haifa War Memorial\", \"reason\": \"Begin your day with a visit to this museum and memorial, offering deep insights into India\'s military history and the Haifa War.\", \"travel_minutes\": 0, \"estimated_duration\": \"2h\"}, {\"time\": \"01:00 PM\", \"place_slug\": \"mahatma-gandhi\", \"place_name\": \"Mahatma Gandhi\", \"reason\": \"Pay homage to the Father of the Nation at this historical site, which offers a glimpse into Gandhi\'s life and philosophy.\", \"travel_minutes\": 6, \"estimated_duration\": \"1.5h\"}, {\"time\": \"04:30 PM\", \"place_slug\": \"ashok-stambh\", \"place_name\": \"Ashok Stambh\", \"reason\": \"Visit this ancient pillar symbolizing Emperor Ashoka\'s legacy, a significant historical artifact located in a peaceful setting.\", \"travel_minutes\": 1, \"estimated_duration\": \"1h\"}, {\"time\": \"07:30 PM\", \"place_slug\": \"parkland-hotel\", \"place_name\": \"Parkland Hotel\", \"reason\": \"Unwind at this park-like setting, perfect for a relaxed evening stroll or enjoying a meal amidst greenery.\", \"travel_minutes\": 10, \"estimated_duration\": \"1.5h\"}]}]', '{\"summary\": \"Explore Goa\'s unique blend of beaches, culture, and local flavors over a relaxing weekend getaway. Enjoy a mix of historical insights and leisure despite the rainy weather.\", \"travel_tips\": [\"Carry waterproof gear and quick-dry clothing due to high rain probability.\", \"Visit indoor or covered attractions during peak rain hours (afternoon) to stay comfortable.\"], \"original_prompt\": \"Weekend getaway to Goa\", \"theme\": \"Heritage & Culture\"}', '{\"weather_summary\": {\"temperature_c\": 25.4, \"condition\": \"Showers & Rain\", \"humidity_pct\": 60, \"rain_probability_pct\": 75, \"recommendation\": \"Opt for indoor or rain-friendly activities to make the most of your trip.\"}}', '2026-08-01 12:48:51', '2026-08-01 12:48:51'),
(26, 'f5ac8a97-f397-4754-8eaf-63a1084bf758', 1, 'Goa', '2 Day Itinerary in Goa', '2 Days', 'Moderate', '[{\"day\": 1, \"theme\": \"Historical Exploration\", \"activities\": [{\"time\": \"09:00 AM\", \"place_slug\": \"red-fort-lal-qila\", \"place_name\": \"Red Fort (Lal Qila)\", \"reason\": \"Start your day with one of India\'s most iconic historical landmarks, offering a glimpse into Mughal architecture and history.\", \"travel_minutes\": 0, \"estimated_duration\": \"2h\"}, {\"time\": \"01:00 PM\", \"place_slug\": \"india-gate\", \"place_name\": \"India Gate\", \"reason\": \"A patriotic and scenic spot for an afternoon stroll, perfect for understanding India\'s colonial history.\", \"travel_minutes\": 1370, \"estimated_duration\": \"1.5h\"}, {\"time\": \"04:30 PM\", \"place_slug\": \"qutub-minar\", \"place_name\": \"Qutub Minar\", \"reason\": \"Explore the tallest brick minaret in the world, a UNESCO World Heritage Site, and enjoy its serene surroundings.\", \"travel_minutes\": 13, \"estimated_duration\": \"1.5h\"}, {\"time\": \"07:30 PM\", \"place_slug\": \"goats-market\", \"place_name\": \"Goats Market\", \"reason\": \"Experience local shopping and vibrant nightlife at this bustling market, perfect for souvenirs and street food.\", \"travel_minutes\": 18, \"estimated_duration\": \"2h\"}]}, {\"day\": 2, \"theme\": \"Cultural and Leisure Day\", \"activities\": [{\"time\": \"09:00 AM\", \"place_slug\": \"lotus-temple\", \"place_name\": \"Lotus Temple\", \"reason\": \"Begin your day with a visit to this architectural marvel, known for its lotus-like design and tranquil ambiance.\", \"travel_minutes\": 0, \"estimated_duration\": \"2h\"}, {\"time\": \"01:00 PM\", \"place_slug\": \"teen-murti-haifa-war-memorial\", \"place_name\": \"Teen Murti Haifa War Memorial\", \"reason\": \"A meaningful visit to this museum and memorial, offering insights into India\'s military history.\", \"travel_minutes\": 14, \"estimated_duration\": \"1.5h\"}, {\"time\": \"04:30 PM\", \"place_slu