(27, '51050ef3-4638-4a74-bd86-eddca5b1dd79', 1, 'Mysore', '3 Day Itinerary in Mysore', '3 Days', 'Moderate', '[{\"day\": 1, \"theme\": \"Historical Exploration\", \"activities\": [{\"time\": \"09:00 AM\", \"place_slug\": \"mysore\", \"place_name\": \"Mysore Palace\", \"reason\": \"Start your trip with the iconic Mysore Palace, a symbol of the city\'s royal heritage and architectural brilliance.\", \"travel_minutes\": 0, \"estimated_duration\": \"2h\"}, {\"time\": \"01:00 PM\", \"place_slug\": \"mysore\", \"place_name\": \"Mysore Zoo\", \"reason\": \"Visit the renowned Mysore Zoo, one of the oldest and most popular zoos in India, home to a diverse range of wildlife.\", \"travel_minutes\": 0, \"estimated_duration\": \"2h\"}, {\"time\": \"04:30 PM\", \"place_slug\": \"mysore\", \"place_name\": \"Chamundi Hill\", \"reason\": \"Enjoy the panoramic views of Mysore from Chamundi Hill and visit the famous Chamundeshwari Temple.\", \"travel_minutes\": 0, \"estimated_duration\": \"1.5h\"}, {\"time\": \"07:30 PM\", \"place_slug\": \"mysore\", \"place_name\": \"Brindavan Gardens\", \"reason\": \"Conclude your day with a visit to Brindavan Gardens, known for its musical fountain and beautifully landscaped gardens.\", \"travel_minutes\": 0, \"estimated_duration\": \"2h\"}]}, {\"day\": 2, \"theme\": \"Cultural and Spiritual Journey\", \"activities\": [{\"time\": \"09:00 AM\", \"place_slug\": \"mysore\", \"place_name\": \"St. Philomena\'s Church\", \"reason\": \"Explore the stunning architecture of St. Philomena\'s Church, one of the largest churches in India.\", \"travel_minutes\": 0, \"estimated_duration\": \"1.5h\"}, {\"time\": \"01:00 PM\", \"place_slug\": \"mysore\", \"place_name\": \"Jaganmohan Palace\", \"reason\": \"Discover the art and history at Jaganmohan Palace, which houses an extensive collection of artifacts and paintings.\", \"travel_minutes\": 0, \"estimated_duration\": \"2h\"}, {\"time\": \"04:30 PM\", \"place_slug\": \"mysore\", \"place_name\": \"Rail Museum\", \